// Host-side mapping — TmChat never interprets the three fields.
private static ChatMessage ToChat(InboxMessageDto dto, ChatUser author) =>
    new(dto.Id, dto.PreviewText, author, ToMessageType(dto.Direction), dto.CreatedAt)
    {
        Kind = dto.State switch
        {
            InboxState.AiDraft => "ai-draft",
            InboxState.Queued => "queued",
            _ => null,
        },
        Metadata = new Dictionary<string, object?>
        {
            ["reason"] = dto.DraftReason,
            ["scheduledFor"] = dto.ScheduledFor,
        },
        Payload = dto, // typed read-back via context.PayloadAs<InboxMessageDto>()
    };

// In the template the original DTO comes back type-safely:
var draft = context.PayloadAs<InboxMessageDto>();

@* The whole registration is the id attribute — AutoAttachComposerInput resolves it *@
<TmChat Messages="_messages" CurrentUser="_user" OnSend="HandleSend"
        ComposerTemplate="AutoComposer" AutoAttachComposerInput="true" />

@code {
    private RenderFragment<ChatComposerContext> AutoComposer => context =>
        @<div class="my-composer">
            <textarea id="@context.InputId"
                      value="@context.Text"
                      @oninput="@(e => context.SetTextAsync(e.Value?.ToString() ?? string.Empty))"></textarea>
            <button disabled="@(!context.CanSend)" @onclick="@(async () => await context.SendAsync())">Send</button>
        </div>;
}
